// Przeplatanie typów w obrębie poziomu, żeby każda dzienna porcja miała słowa, kolokacje, phrasal verbs i zwroty.
// Każda pozycja dostaje klucz (numer w swoim typie + 0.5) / liczba pozycji tego typu, potem sortujemy w obrębie poziomu.
(function(){for(const lv of B2_LEVELS){const items=B2_WORDS.filter(w=>w.level===lv),cnt={},idx={};
  for(const w of items)cnt[w.type]=(cnt[w.type]||0)+1;
  const keyed=items.map(w=>{const i=idx[w.type]=(idx[w.type]||0)+1;return [(i-0.5)/cnt[w.type],w]});
  keyed.sort((a,b)=>a[0]-b[0]);WORDS.push(...keyed.map(k=>k[1]))}})();

// Gramatyka B2. GB = G z poziomem.
const GB=(topic,q,opts,a,why)=>Object.assign(G(topic,q,opts,a,why),{level:'B2'});
